import { useEffect, useMemo, useState } from 'react'
import { CheckCircle2, Minus, Plus, Receipt, Search, Trash2 } from 'lucide-react'
import { catalogApi, posApi, type Customer, type Product, type Vendor } from '../../api'
import { Button } from '../../components/ui/button'
import { Card, CardContent, CardHeader } from '../../components/ui/card'
import { Input } from '../../components/ui/input'

export function PosPage({ vendor, storeId }: { vendor?: Vendor; storeId?: number }) {
  const [products, setProducts] = useState<Product[]>([])
  const [customers, setCustomers] = useState<Customer[]>([])
  const [search, setSearch] = useState('')
  const [cart, setCart] = useState<{ product: Product; quantity: number }[]>([])
  const [tendered, setTendered] = useState('')
  const [discount, setDiscount] = useState('0')
  const [customerId, setCustomerId] = useState('')
  const [paymentMethod, setPaymentMethod] = useState('CASH')
  const [message, setMessage] = useState('')
  const [busy, setBusy] = useState(false)
  useEffect(() => { if (!vendor) return; catalogApi.products(vendor.id, search).then(setProducts).catch(() => setProducts([])) }, [vendor, search])
  useEffect(() => { if (vendor && storeId) posApi.customers(vendor.id, storeId).then(setCustomers).catch(() => setCustomers([])) }, [vendor, storeId])
  const subtotal = useMemo(() => cart.reduce((sum, item) => sum + item.product.retailPrice * item.quantity, 0), [cart])
  const total = Math.max(0, subtotal - Number(discount || 0))
  function add(product: Product) { setCart(current => { const found = current.find(item => item.product.id === product.id); return found ? current.map(item => item.product.id === product.id ? { ...item, quantity: item.quantity + 1 } : item) : [...current, { product, quantity: 1 }] }) }
  async function completeSale() { if (!vendor || !storeId || !cart.length) return; setBusy(true); setMessage(''); try { const sale = await posApi.sale(vendor.id, storeId, cart.map(item => ({ productId: item.product.id, quantity: item.quantity })), tendered ? Number(tendered) : undefined, Number(discount || 0), paymentMethod, customerId ? Number(customerId) : undefined); setMessage(`Sale ${sale.receiptNumber} completed. Total: PHP ${sale.totalAmount.toLocaleString()}`); setCart([]); setTendered(''); setDiscount('') } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to complete sale.') } finally { setBusy(false) } }
  return <><div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-indigo-600">Sales operations</p><h1 className="mt-1.5 text-3xl font-black tracking-[-.055em]">Point of sale</h1><p className="mt-2 text-[13px] text-slate-500">Search or scan a product, add it to the cart, collect payment, and record the sale.</p></div>{message && <p className="mb-4 rounded-xl bg-emerald-50 p-3 text-sm font-semibold text-emerald-700">{message}</p>}<div className="grid gap-5 xl:grid-cols-[1fr_380px]"><Card><CardHeader><div className="relative"><Search className="absolute left-3 top-3 text-slate-400" size={17} /><Input className="pl-9" placeholder="Search products by name or SKU" value={search} onChange={event => setSearch(event.target.value)} /></div></CardHeader><CardContent><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{products.map(product => <button key={product.id} onClick={() => add(product)} className="rounded-xl border border-slate-100 p-4 text-left hover:border-indigo-200 hover:bg-indigo-50"><strong className="block text-sm">{product.name}</strong><span className="mt-1 block text-xs text-slate-500">{product.sku}</span><span className="mt-3 block font-black">PHP {product.retailPrice.toLocaleString()}</span></button>)}{!products.length && <p className="col-span-full p-8 text-center text-sm text-slate-500">No products found.</p>}</div></CardContent></Card><Card><CardHeader><div className="flex items-center justify-between"><h2 className="font-bold">Current sale</h2><span className="text-xs text-slate-500">{cart.length} items</span></div></CardHeader><CardContent><div className="space-y-3">{cart.map(item => <div key={item.product.id} className="flex items-center gap-2 rounded-lg bg-slate-50 p-2"><div className="min-w-0 flex-1"><strong className="block truncate text-xs">{item.product.name}</strong><span className="text-xs text-slate-500">PHP {item.product.retailPrice.toLocaleString()}</span></div><button onClick={() => setCart(current => current.map(row => row.product.id === item.product.id ? { ...row, quantity: Math.max(1, row.quantity - 1) } : row))}><Minus size={14} /></button><span className="w-5 text-center text-xs font-bold">{item.quantity}</span><button onClick={() => add(item.product)}><Plus size={14} /></button><button onClick={() => setCart(current => current.filter(row => row.product.id !== item.product.id))}><Trash2 size={14} className="text-rose-500" /></button></div>)}{!cart.length && <p className="py-8 text-center text-sm text-slate-500">Add products to begin.</p>}</div><div className="mt-5 space-y-2 border-t border-slate-100 pt-4"><div className="flex justify-between text-sm"><span>Subtotal</span><strong>PHP {subtotal.toLocaleString()}</strong></div><label className="block text-xs font-semibold text-slate-600">Discount<Input type="number" min="0" value={discount} onChange={event => setDiscount(event.target.value)} /></label><div className="flex justify-between text-lg font-black"><span>Total</span><span>PHP {total.toLocaleString()}</span></div><div className="grid grid-cols-2 gap-2"><select className="rounded-lg border border-slate-200 px-2 text-xs" value={paymentMethod} onChange={event => setPaymentMethod(event.target.value)}><option>CASH</option><option>GCASH</option><option>CARD</option></select><Input type="number" min="0" placeholder="Amount tendered" value={tendered} onChange={event => setTendered(event.target.value)} /></div><select className="w-full rounded-lg border border-slate-200 px-2 py-2 text-xs" value={customerId} onChange={event => setCustomerId(event.target.value)}><option value="">Walk-in customer</option>{customers.map(customer => <option key={customer.id} value={customer.id}>{customer.name}</option>)}</select><Button className="w-full" disabled={busy || !cart.length || !storeId} onClick={completeSale}><Receipt size={16} /> {busy ? 'Processing...' : 'Complete sale'}</Button></div></CardContent></Card></div></>
}
